 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != background and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)
    template = max(components, key=len)
    r0 = min(r for r, c in template)
    r1 = max(r for r, c in template)
    c0 = min(c for r, c in template)
    c1 = max(c for r, c in template)
    rh, rw = r1-r0+1, c1-c0+1
    out = [row[:] for row in grid]
    markers = [comp[0] for comp in components if comp is not template and len(comp) == 1]
    for mr, mc in markers:
        out[mr][mc] = background
        top, left = mr-rh//2, mc-rw//2
        for rr in range(rh):
            for cc in range(rw):
                value = grid[r0+rr][c0+cc]
                if value != background and 0 <= top+rr < h and 0 <= left+cc < w:
                    out[top+rr][left+cc] = value
    return out
